11.query:
timeseries master_objects = sum(aerospike_namespace_master_objects, filter: { cluster_name == $cluster and in(ns, array($namespace)) }, rollup: avg), by: { ns }
| append [
  timeseries a0 = sum(aerospike_namespace_data_used_bytes, filter: { cluster_name == $cluster and in(ns, array($namespace)) }, rollup: avg), a1 = sum(aerospike_namespace_data_compression_ratio, filter: { cluster_name == $cluster and in(ns, array($namespace)) }, rollup: avg), a2 = sum(aerospike_namespace_effective_replication_factor, filter: { cluster_name == $cluster and in(ns, array($namespace)) }, rollup: avg), by: { service, ns }
  | fieldsAdd value = ((a0[] / a1[]) / a2[])
  | fieldsRemove a0, a1, a2
  | summarize value = sum(value[]), by: { timeframe, interval, ns }
  | summarize value = sum(value[]), by: { timeframe, interval }
  | fieldsRename unique_bytes = value
]
| fields ns, master_objects = coalesce(master_objects[-2], arrayLast(master_objects)), unique_bytes = coalesce(unique_bytes[-2], arrayLast(unique_bytes))

